{
  "decision": "NO_CHANGE",
  "workflow_yaml": null,
  "rationale": "The workflow already applies dependency caching (pnpm store cache keyed on pnpm-lock.yaml) and stale-run cancellation (concurrency group with cancel-in-progress: true). The candidate P-LIT-FAIL-FAST (changing the browser matrix from fail-fast: false to true) is not supported because every matrix outcome is required for cross-browser coverage and full failure diagnostics; cancelling remaining browser jobs on failure would reduce intended test coverage. P-LIT-CUSTOM-TIMEOUT does not apply because both jobs already declare explicit timeouts (40 and 30 minutes). No other catalogue pattern fits this workflow without weakening coverage, adding untrusted cache writes, or requiring infrastructure changes outside the workflow scope.",
  "evidence_ids": ["pattern:P-LIT-FAIL-FAST", "pattern:P-LIT-GHA-CACHE", "pattern:P-LIT-CANCEL-STALE", "pattern:P-LIT-CUSTOM-TIMEOUT"]
}
